/* ===== V33.31 · «Explorador»: tour guiado por las funciones de Isoflux (Vista) + guía PDF =====
   Agrega en el menu Vista un boton «Explorador» que inicia un recorrido con foco (spotlight)
   sobre cada menu/boton/modal, describiendo la potencia de la herramienta, y permite descargar
   la guia en PDF (incrustado, funciona sin conexion). Solo agrega UI; no toca el calculo. */
(function(){
 const STEPS=[{"sel": "#bsv", "icon": "🧭", "title": "Flujo de trabajo", "desc": "La barra superior sigue el orden natural del trabajo, de izquierda a derecha: Archivo, Vista, Dibujo y parámetros, Anotación, Selección, Cálculo, Simulación y Ayuda. Todo el modelador cabe en una sola pantalla, sin instalar nada."}, {"sel": "#bsv", "icon": "📁", "title": "Archivo y proyecto", "desc": "Guarda el proyecto como un archivo .html autónomo (lleva el dibujo, los datos y los fondos dentro), crea dibujos nuevos y genera una versión de solo lectura para compartir con quien no edita."}, {"sel": "#bpj", "icon": "🗂️", "title": "Portal de proyectos", "desc": "Conecta el dibujo con el registro de proyectos del Hub (Google Sheets y Drive): guardar, versionar y recuperar planos por proyecto, con control de acceso."}, {"sel": "#btour", "icon": "🎥", "title": "Vista y navegación", "desc": "Órbita, encuadre, vistas ISO/planta/frente/lateral, recorrido automático tipo video, rotación y modo 3D proporcional o CAD unifilar. El dibujo conserva proporciones reales al hacer zoom."}, {"sel": "#nivHud", "icon": "⛰", "title": "Niveles / plantas", "desc": "Trabaja la red por pisos: crea plantas a distinta altura, activa la planta donde dibujas y muestra u oculta los planos de nivel. Ideal para edificios y montajes en varios niveles."}, {"sel": "canvas", "icon": "🛢️", "title": "Tanques y VaporGLP", "desc": "Dibuja tanques en 3D a escala real con sus bases y casquetes. Un clic abre VaporGLP: calcula la vaporización del GLP según temperatura, nivel y geometría, su presión de vapor y la capacidad de suministro. Varios tanques en un mismo manifold suman su capacidad."}, {"sel": "canvas", "icon": "🔧", "title": "Dibujo y componentes", "desc": "Traza tuberías en isométrico imantando puntos y fijando longitudes exactas; inserta válvulas, reguladores, manómetros y medidores sobre la tubería; asigna diámetro, material, presión y nivel a uno o a varios a la vez."}, {"sel": "#bsim", "icon": "▶️", "title": "Simulación de operación", "desc": "Resuelve toda la red: caudal, velocidad y caída de presión por tramo, con la presión de la fuente tomada automáticamente del tanque o del distribuidor. Evalúa si la fuente alcanza la demanda y marca los tramos críticos."}, {"sel": "#bcal", "icon": "🧮", "title": "Memoria de cálculo", "desc": "El detalle del cálculo tramo por tramo: método (Pole, Renouard, Weymouth…), gas, presiones, Ø interno, longitud equivalente, velocidad y caída. Se exporta a PDF, Excel y JSON."}, {"sel": "#bres", "icon": "📈", "title": "Resultados sobre el dibujo", "desc": "Muestra caudal, velocidad y caída directamente sobre cada tramo, con tarjetas que puedes limitar (1 a todas) para controlar el ruido visual en redes grandes."}, {"sel": "#bps79", "icon": "🧠", "title": "Psinapsis — asistente", "desc": "La red neuronal de Isoflux: pregúntale al dibujo en lenguaje natural (por texto o voz). Resume la red, explica presiones, sugiere mejoras, estima costos y hasta presenta el proyecto al cliente. Es una tarjeta arrastrable."}, {"sel": "#bcrn", "icon": "📅", "title": "Cronograma y obra", "desc": "Genera el cronograma de mantenimiento y el plan de obra (Gantt) a partir del proyecto, para pasar del diseño a la ejecución sin reescribir datos."}, {"sel": "#baud", "icon": "⚖️", "title": "Normas y cumplimiento", "desc": "Carga normas (PDF, Excel o enlaces) y compara el diseño contra ellas: caídas y velocidades admisibles, clasificación de presión y fichas normativas de tanques y equipos."}, {"sel": "#bpall", "icon": "📄", "title": "Entregables", "desc": "PDF consolidado (plano + memoria de cálculo), exportación a AutoCAD (DXF) y video de giro 360° del dibujo: documentación lista para el cliente y la interventoría."}, {"sel": "#bhelp", "icon": "❓", "title": "Ayuda y esta guía", "desc": "El manual de uso vive en el botón Ayuda; desde allí también descargas el «Perfil de usuario (PDF)» y esta guía del Explorador. Todo funciona sin conexión."}];
 const PDF_B64="";
 const g=id=>document.getElementById(id);
 const toast=m=>{try{(window.bgToast||console.log)(m);}catch(e){}};
 const esc=s=>String(s==null?'':s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
 let cur=0,ov=null,spot=null,card=null,restore=null,active=false;

 function build(){
  ov=document.createElement('div');ov.id='explOv';
  ov.style.cssText='position:fixed;inset:0;z-index:100000;display:none;background:transparent';
  spot=document.createElement('div');spot.id='explSpot';
  spot.style.cssText='position:fixed;border-radius:10px;pointer-events:none;z-index:100001;display:none;border:2px solid #4f9bff;box-shadow:0 0 0 9999px rgba(6,10,16,.70),0 0 16px #2f86e8;transition:left .25s,top .25s,width .25s,height .25s';
  card=document.createElement('div');card.id='explCard';
  card.style.cssText='position:fixed;z-index:100002;width:min(360px,92vw);background:linear-gradient(145deg,#141c2b,#0d1420);border:1px solid #2f6fcf;border-radius:14px;box-shadow:0 16px 50px #000b;padding:15px 16px;color:#e4eefa;font:14px/1.5 "IBM Plex Sans",system-ui,sans-serif;display:none';
  document.body.append(ov,spot,card);
  document.addEventListener('keydown',onKey,true);
 }
 function onKey(e){if(!active)return;if(e.key==='Escape'){e.preventDefault();e.stopPropagation();stop();}else if(e.key==='ArrowRight'||e.key===' '){e.preventDefault();e.stopPropagation();go(cur+1);}else if(e.key==='ArrowLeft'){e.preventDefault();e.stopPropagation();go(cur-1);}}

 function revealTarget(sel){
  let el=null;try{el=sel?document.querySelector(sel):null;}catch(e){}
  const opened=[];
  if(el){let d=el.closest&&el.closest('details');while(d){if(!d.open){d.open=true;opened.push(d);}d=d.parentElement&&d.parentElement.closest('details');}}
  restore=()=>opened.forEach(d=>{try{d.open=false;}catch(e){}});
  return el;
 }
 function rectOf(el){try{const r=el.getBoundingClientRect();if(r.width>2&&r.height>2&&r.bottom>0&&r.top<innerHeight)return r;}catch(e){}return null;}

 /* mide el objetivo AHORA (se re-consulta por si el nodo cambió) y coloca el foco con precisión */
 function place(){
  const s=STEPS[cur];let el=null;try{el=s&&s.sel?document.querySelector(s.sel):null;}catch(e){}
  const r=el?rectOf(el):null;
  if(r){const p=6;spot.style.display='block';spot.style.left=(r.left-p)+'px';spot.style.top=(r.top-p)+'px';spot.style.width=(r.width+p*2)+'px';spot.style.height=(r.height+p*2)+'px';}
  else spot.style.display='none';
  return r;
 }
 function go(i){
  if(restore){try{restore();}catch(e){}restore=null;}
  cur=Math.max(0,Math.min(STEPS.length-1,i));
  revealTarget(STEPS[cur].sel);        /* abre los <details> ancestros si el objetivo está en un menú */
  spot.style.transition='none';        /* sin animación hasta ubicarlo bien */
  const r0=place();renderCard(r0);
  /* re-ubica mientras el layout asienta (menús que abren, fuentes, reflow): evita el desfase */
  requestAnimationFrame(()=>{positionCard(place());
   requestAnimationFrame(()=>{positionCard(place());});});
  setTimeout(()=>{positionCard(place());spot.style.transition='left .18s,top .18s,width .18s,height .18s';},150);
  setTimeout(()=>{positionCard(place());},320);
 }
 function renderCard(r){
  const s=STEPS[cur],n=STEPS.length;
  card.innerHTML='<div style="display:flex;align-items:center;gap:9px;margin-bottom:7px">'
   +'<span style="font-size:20px">'+(s.icon||'•')+'</span>'
   +'<b style="font-family:Archivo,system-ui,sans-serif;font-size:16px;color:#f3f8ff;flex:1">'+esc(s.title)+'</b>'
   +'<span style="font-size:11.5px;color:#90a3bd">'+(cur+1)+'/'+n+'</span></div>'
   +'<div style="color:#cdd9ea;font-size:13.5px">'+esc(s.desc)+'</div>'
   +'<div style="height:4px;background:#1b2740;border-radius:3px;margin:12px 0 11px;overflow:hidden"><div style="height:100%;width:'+Math.round((cur+1)/n*100)+'%;background:linear-gradient(90deg,#2f86e8,#5aa6ff)"></div></div>'
   +'<div style="display:flex;gap:7px;align-items:center;flex-wrap:wrap">'
   +'<button data-ex="prev" '+(cur===0?'disabled':'')+' style="padding:6px 11px">‹ Anterior</button>'
   +'<button data-ex="next" style="padding:6px 13px;background:#1d5fd8;border-color:#2f86e8;color:#fff;font-weight:600">'+(cur===n-1?'Terminar':'Siguiente ›')+'</button>'
   +'<span style="flex:1"></span>'
   +'<button data-ex="pdf" title="Descargar la guia del Explorador en PDF" style="padding:6px 10px">⬇ Guia PDF</button>'
   +'<button data-ex="exit" title="Salir del Explorador" style="padding:6px 10px">✕</button></div>';
  positionCard(r);
  card.style.display='block';
  card.querySelectorAll('[data-ex]').forEach(b=>b.onclick=()=>{const a=b.dataset.ex;if(a==='next'){cur===n-1?stop():go(cur+1);}else if(a==='prev')go(cur-1);else if(a==='exit')stop();else if(a==='pdf')dlPdf();});
 }
 function positionCard(r){
  const m=12,cw=Math.min(360,innerWidth-24);card.style.width=cw+'px';
  const ch=card.offsetHeight||230;let left,top;
  if(r){left=Math.min(Math.max(m,r.left),innerWidth-cw-m);
   if(r.bottom+ch+m<innerHeight)top=r.bottom+m;
   else if(r.top-ch-m>0)top=r.top-ch-m;
   else{top=Math.max(m,innerHeight-ch-m);}
  }else{left=(innerWidth-cw)/2;top=Math.max(m,(innerHeight-ch)/2);}
  card.style.left=left+'px';card.style.top=top+'px';
 }
 function start(){if(!ov)build();active=true;ov.style.display='block';go(0);}
 function stop(){active=false;if(restore){try{restore();}catch(e){}restore=null;}if(ov)ov.style.display='none';if(spot)spot.style.display='none';if(card)card.style.display='none';}
 function dlPdf(){try{const bin=atob(PDF_B64),len=bin.length,by=new Uint8Array(len);for(let i=0;i<len;i++)by[i]=bin.charCodeAt(i);const blob=new Blob([by],{type:'application/pdf'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Explorador_Isoflux.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('⬇️ Descargando la guia del Explorador (PDF)');}catch(e){toast('No se pudo descargar: '+e.message);}}

 function addBtn(){const tb=g('btour');if(!tb)return false;if(g('bexpl'))return true;
  const b=document.createElement('button');b.id='bexpl';b.textContent='🧭 Explorador';
  b.title='Tour guiado por las funciones de Isoflux (y descarga la guia en PDF)';
  b.onclick=()=>start();tb.parentNode.insertBefore(b,tb);return true;}
 let k=0;const t=setInterval(()=>{if(addBtn()||++k>60)clearInterval(t);},300);
 addEventListener('resize',()=>{if(active)positionCard(place());});
 addEventListener('scroll',()=>{if(active)positionCard(place());},true);
 window.EXPLORADOR={start,stop,dlPdf};
})();
